// ConnectorSignInMethod ConnectorSignInMethod is a way to sign in: "guided" (Foundry runs the tool's sign-in on the device and relays the challenge) or "terminal" (the person runs Commands there; Foundry only checks).
type ConnectorSignInMethod struct {
	// ID Sent to the adapter as `signInOptions.method`.
	ID           string            `json:"id"`
	Kind         string            `json:"kind"`
	Label        string            `json:"label"`
	Labels       map[string]string `json:"labels,omitempty"`
	Description  string            `json:"description,omitempty"`
	Descriptions map[string]string `json:"descriptions,omitempty"`
	Fields       []ConnectorField  `json:"fields,omitempty"`

	// Commands terminal: what to run there, the first being the usual one.
	Commands []string `json:"commands,omitempty"`

	// ScopesGroup guided: the authorization group whose scopes the person chooses before signing in; the choice reaches the adapter as signInOptions.scopes (comma-separated).
	ScopesGroup string `json:"scopesGroup,omitempty"`
}

// ConnectorSignInRepeat The label of the offer to sign in again.
type ConnectorSignInRepeat struct {
	Label  string            `json:"label"`
	Labels map[string]string `json:"labels,omitempty"`
}

// ConnectorSourceAccess A connector is visible only when one of the owner's devices can read the repository through the named Foundry connector.
type ConnectorSourceAccess struct {
	// Via A connector kind that declares repositoryAccess.
	Via string `json:"via"`

	// Repository owner/repo or an https repository address.
	Repository string            `json:"repository"`
	Hint       string            `json:"hint,omitempty"`
	Hints      map[string]string `json:"hints,omitempty"`
}

// ConnectorSourceAccessCheck A device's last check of one source repository through a Foundry connector.
type ConnectorSourceAccessCheck struct {
	Status    string `json:"status"`
	CheckedAt string `json:"checkedAt"`

	// Identity The non-secret account name of the connector login used.
	Identity string `json:"identity,omitempty"`

	// Detail A short non-secret message from the connector.
	Detail string `json:"detail,omitempty"`
}

// ConnectorTool ConnectorTool is the program a connector's sessions use and where Foundry installs it from ("npm" through the managed-tools path, "installer" through the vendor's official per-user installer, which the worker's adapter runs). MinimumVersion marks older copies as outdated.
type ConnectorTool struct {
	Command string `json:"command"`

	// Source "device": installed outside Foundry; "npm": a managed package; "installer": the vendor's official per-user installer, run by the worker's adapter at the owner's click.
	Source  string `json:"source,omitempty"`
	Package string `json:"package,omitempty"`

	// Registry Where the package comes from; "device" is the device's own npm settings.
	Registry string `json:"registry,omitempty"`

	// MinimumVersion Older copies work worse or not at all ("2.0.0" for AWS CLI v2).
	MinimumVersion string `json:"minimumVersion,omitempty"`

	// VersionCheck ConnectorVersionCheck is what checking a new version of the connector's tool runs on a bundle rollout's canary device, after `--version`, in the session environment the connector gives a session (docs/skills.md, Bundle 版本). Every command must exit 0.
	VersionCheck *ConnectorVersionCheck `json:"versionCheck,omitempty"`
}

// ConnectorVersionCheck ConnectorVersionCheck is what checking a new version of the connector's tool runs on a bundle rollout's canary device, after `--version`, in the session environment the connector gives a session (docs/skills.md, Bundle 版本). Every command must exit 0.
type ConnectorVersionCheck struct {
	Commands jsonempty.List[ConnectorVersionCheckCommand] `json:"commands"`
}

// ConnectorVersionCheckCommand defines model for ConnectorVersionCheckCommand.
type ConnectorVersionCheckCommand struct {
	// Args The tool's arguments; the tool itself is the connector's command.
	Args jsonempty.List[string] `json:"args"`

	// Expect Text the output must contain.
	Expect string `json:"expect,omitempty"`

	// Result What a passed run shows people, in one line instead of its output (which can name the account) - "status" (signed in, token valid), "refresh" (token refreshed) or "read" (reached the service as the account, named by show).
	Result ConnectorVersionCheckCommandResult `json:"result,omitempty"`

	// Show A dotted path into the command's JSON output whose value the one-line result names (e.g. data.name for the account's display name). Nothing else of the output is kept.
	Show string `json:"show,omitempty"`
}

// ConnectorVersionCheckCommandResult What a passed run shows people, in one line instead of its output (which can name the account) - "status" (signed in, token valid), "refresh" (token refreshed) or "read" (reached the service as the account, named by show).
type ConnectorVersionCheckCommandResult string

// DeviceConnectorSessionCheck DeviceConnectorSessionCheck separates `signed in` from `usable in a session`. The worker builds the environment a session that may use the login gets, and the one a session that may not gets, from the same code that starts sessions, and checks in them: the tool is found, the login reads as signed in and what the connector promises works (GitHub: git gets github.com credentials) in the first; nothing yields a credential in the second. It never holds a credential.
type DeviceConnectorSessionCheck struct {
	// Usable The connector works in the environment of a session that may use it.
	Usable bool `json:"usable"`

	// Reason Why it does not (the tool's or the check's own words, no credential).
	Reason string `json:"reason,omitempty"`

	// IsolationHolds A session that may not use the login gets none of it. Absent when the connector has nothing to isolate or the check could not run.
	IsolationHolds *bool `json:"isolationHolds,omitempty"`

	// IsolationReason What still yielded a credential, when isolation does not hold.
	IsolationReason string `json:"isolationReason,omitempty"`
	CheckedAt       string `json:"checkedAt"`
}

// DeviceConnectorState DeviceConnectorState is a device-held connector on one device as last read there. It never holds a credential.
type DeviceConnectorState struct {
	Authorizations []ConnectorAuthorizationState `json:"authorizations,omitempty"`
	DeviceID       string                        `json:"deviceId"`
	Kind           string                        `json:"kind"`

	// Status Where a device-held connector stands on one device.
	Status DeviceConnectorStatus `json:"status"`

	// StatusDetail Why it is unavailable or failed (a requirement's label, an error).
	StatusDetail string `json:"statusDetail,omitempty"`

	// Configuration Non-secret settings read from the connector's active profile.
	Configuration *ConnectorConfiguration `json:"configuration,omitempty"`
	Installed     bool                    `json:"installed"`
	Version       string                  `json:"version,omitempty"`

	// InstallSource "foundry": installed by Foundry's managed tools; "device": the device's own.
	InstallSource string `json:"installSource,omitempty"`

	// LatestVersion The newest version the device's package source offers, when known.
	LatestVersion string   `json:"latestVersion,omitempty"`
	SignedIn      bool     `json:"signedIn"`
	Identity      string   `json:"identity,omitempty"`
	Sites         []string `json:"sites,omitempty"`
	ExpiresAt     string   `json:"expiresAt,omitempty"`
	CheckedAt     string   `json:"checkedAt"`

	// ExpiringSince When a check first found the login inside the reminder window.
	ExpiringSince string `json:"expiringSince,omitempty"`

	// SessionCheck `sessionCheck` is what checking the connector in the environments a session gets found (see DeviceConnectorSessionCheck). Absent while the login is not read or before the first check.
	SessionCheck *DeviceConnectorSessionCheck `json:"sessionCheck,omitempty"`
}

// DeviceConnectorStatus Where a device-held connector stands on one device.
type DeviceConnectorStatus = string

// DeviceConnectorUse DeviceConnectorUse rides run_session: what the session may do with a device-held connector on its device ("device_login" or "none").
type DeviceConnectorUse struct {
	// State `state` is checked metadata only, including separate authorization groups.
	State        *DeviceConnectorState `json:"state,omitempty"`
	Kind         string                `json:"kind"`
	Adapter      string                `json:"adapter"`
	Label        string                `json:"label"`
	Command      string                `json:"command"`
	Access       string                `json:"access"`
	IsolationEnv map[string]string     `json:"isolationEnv,omitempty"`
}

// ExternalAccountGateway ExternalAccountGateway is a session's way through the server's gateway for one account: the server path the device's loopback forwarder sends the tool's requests under, and the opaque handles the tool holds in place of the app secret, the user access token and the user refresh token. A handle is useless without the device's credential and dies with the session.
type ExternalAccountGateway struct {
	ExpiresAt string `json:"expiresAt,omitempty"`

	// Path Server path the device's loopback forwarder sends requests under.
	Path string `json:"path"`

	// AppHandle Stands in for the app secret.
	AppHandle string `json:"appHandle"`

	// UserHandle Stands in for the user access token.
	UserHandle string `json:"userHandle"`

	// RefreshHandle Stands in for the user refresh token; the gateway answers its refresh.
	RefreshHandle string `json:"refreshHandle,omitempty"`
}

// ExternalAccountMaterial ExternalAccountMaterial is what a worker needs to let one tool act as an account for one session: the identity, the tool's profile and the gateway handles that stand in for the app secret and the access token. No secret and no real token ever rides it: the tool reaches the provider through the server's gateway (internal/feishugateway), which swaps the handles for the real credentials. It rides run_session and is written into a tool profile the worker removes when the session ends.
type ExternalAccountMaterial struct {
	AccountID string `json:"accountId"`
	Provider  string `json:"provider"`
	Label     string `json:"label"`

	// Tool `tool` is the program the material is for (feishu-cli); ProfileName the profile the worker writes and selects for the session.
	Tool        string `json:"tool"`
	ProfileName string `json:"profileName"`
	ClientID    string `json:"clientId"`

	// Gateway `gateway` is how the tool reaches the provider through Foundry.
	Gateway *ExternalAccountGateway `json:"gateway,omitempty"`

	// ExpiresAt `expiresAt` bounds the handles for the tool's own expiry checks; the server stops honouring them as soon as the session ends.
	ExpiresAt   string `json:"expiresAt"`
	Scope       string `json:"scope,omitempty"`
	Subject     string `json:"subject,omitempty"`
	DisplayName string `json:"displayName,omitempty"`

	// ProviderAccountID `providerAccountId` is the provider's own account id that the tool is told natively (Cloudflare: CLOUDFLARE_ACCOUNT_ID, so `cf` finds a zone by domain without listing accounts). Set only when everything the account is bound to belongs to that one account; it is not a secret.
	ProviderAccountID string `json:"providerAccountId,omitempty"`

	// SessionEnvironment Environment templates for a server-held extension's session. Worker renders `{gatewayBase}` and `{standIn}`; field references are already rendered by Server.
	SessionEnvironment map[string]string `json:"sessionEnvironment,omitempty"`
}

// SaveAppStoreConnectKeyInput SaveAppStoreConnectKeyInput stores an App Store Connect API key. The issuer and key ids are public metadata; privateKey is write-only and is sealed by the server.
type SaveAppStoreConnectKeyInput struct {
	IssuerID   string `json:"issuerId"`
	KeyID      string `json:"keyId"`
	PrivateKey string `json:"privateKey,omitempty"`
	Label      string `json:"label,omitempty"`
}

// SetConnectorPackageDevicesInput Replace the devices on which a package is enabled.
type SetConnectorPackageDevicesInput struct {
	DeviceIDs jsonempty.List[string] `json:"deviceIds"`
}
